INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "韦昭度", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：韦昭度。", "biography": null, "status": "draft", "id": "4d186310-6106-56bc-9a34-fa1d5d5d7894"}, {"name": "陈敬瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的陈敬瑄：此前许诺以东川酬赏高仁厚。", "biography": null, "status": "draft", "id": "ad1f9c74-f6fd-50ff-b6c3-679c0c591a71"}, {"name": "徐耕", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：徐耕。", "biography": null, "status": "draft", "id": "67b569de-0684-5f44-ab7a-7ebdfdc09f4c"}, {"name": "田令孜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的田令孜：担忧杨师立作乱。", "biography": null, "status": "draft", "id": "5080b636-4944-5887-afed-2195aeb4a567"}, {"name": "王建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“蜀王与晋王讨论讨梁及称帝”中为致书提议者。", "biography": null, "status": "draft", "id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"name": "周庠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：周庠。", "biography": null, "status": "draft", "id": "fb440e5b-1571-58ce-8ca0-85a0e1b24122"}, {"name": "唐友通", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：唐友通。", "biography": null, "status": "draft", "id": "fcc94ce3-7434-56e9-96e8-b81302bc3c27"}, {"name": "骆保", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：骆保。", "biography": null, "status": "draft", "id": "47a25656-a4d7-50f7-a2b1-94cf4bfbe16c"}, {"name": "王鹞", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：王鹞。", "biography": null, "status": "draft", "id": "7063e87b-e4a2-5576-b8df-3613c2877307"}, {"name": "王宗渥", "aliases": ["郑渥"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：王宗渥。", "biography": null, "status": "draft", "id": "074ad7aa-1f2a-5ccb-8908-de4ce6ab0adf"}, {"name": "周岳", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：周岳。", "biography": null, "status": "draft", "id": "9485af1c-62f2-5a2e-9aa9-f6dba9c278ed"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "赫连铎", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：赫连铎。", "biography": null, "status": "draft", "id": "b54a0fc9-ea29-5e0d-9d2a-f8fe5be8cda9"}, {"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5672-9403-eb349ca77e6e"}, {"name": "刘威", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“楚军击败刘存等淮南水军，攻取岳州”中为淮南应援使。", "biography": null, "status": "draft", "id": "17e4c5b9-67b6-514b-9eb8-1eb8aa66133f"}, {"name": "朱延寿", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：朱延寿。", "biography": null, "status": "draft", "id": "6959c029-8c09-5670-bd4a-ace827cbbea8"}, {"name": "孙儒", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：孙儒。", "biography": null, "status": "draft", "id": "4426793f-0bd8-5a79-919f-7e3a0ddae520"}, {"name": "康暀", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：康暀。", "biography": null, "status": "draft", "id": "2bec5af6-e956-5e29-8182-d0e72b859293"}, {"name": "安景思", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：安景思。", "biography": null, "status": "draft", "id": "0139d7c4-0817-5189-9109-522d7825275d"}, {"name": "李祐", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：李祐。", "biography": null, "status": "draft", "id": "d67fa40a-82d3-5fcf-9fa9-f0b74c5115e9"}, {"name": "李神福", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李神福，在此段中为用疑兵解围者。", "biography": null, "status": "draft", "id": "61a41119-a9f8-5beb-8356-77ed00b4ae34"}, {"name": "石善友", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：石善友。", "biography": null, "status": "draft", "id": "97a6e7f7-bce4-5b40-ba11-82a390a77c43"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "成都围城粮尽，贩米仍难济饥", "start_year": 891, "end_year": 891, "time_original": "891年四月后条；围城期间", "dynasty": "唐", "description": "成都粮食短缺，弃儿满路，居民偷从行营贩米入城。韦昭度与陈敬瑄均准其救饥，贩米渐多但数量极少，米价高昂，饿死者众。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1b0888d7-ed15-5839-8328-280830cbb99d"}, {"title": "陈敬瑄诛欲降者，徐耕受逼杀俘", "start_year": 891, "end_year": 891, "time_original": "891年四月后条；围城期间", "dynasty": "唐", "description": "军民强弱相欺，酷刑不能止；陈敬瑄捕杀谋出降者族党。内外都指挥使、眉州刺史徐耕仁恕，书载保全数千人；田令孜以不刑一人质疑其有异志，徐耕惧而夜杀俘囚于市。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2cb1e221-4fd3-5d50-bcd3-7d5ac46fcc27"}, {"title": "王建拒罢兵，周庠劝独攻成都", "start_year": 891, "end_year": 891, "time_original": "891年四月条；见罢兵制书后", "dynasty": "唐", "description": "王建见罢兵制书不愿撤围，询周庠；周庠劝请韦昭度还朝、独攻成都。王建上表请继续讨陈敬瑄田令孜，又说韦昭度宜返朝谋关东大事，由自己负责平定成都。", "phases": [], "location_name": "成都行营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8b5e937a-859d-5fc6-b68b-3cdcd8179651"}, {"title": "王建令唐友通等杀食骆保以胁韦昭度", "start_year": 891, "end_year": 891, "time_original": "891年四月庚子", "dynasty": "唐", "description": "王建暗令东川将唐友通等擒韦昭度亲吏骆保于行府门，脔食之，称其盗军粮，以此恐吓韦昭度。", "phases": [], "location_name": "行府门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "861dc760-fe56-5afb-827f-c347a2002634"}, {"title": "韦昭度授王建印节，东还京师", "start_year": 891, "end_year": 891, "time_original": "891年四月庚子及其后", "dynasty": "唐", "description": "韦昭度惊惧称病，将印节授王建，牒其知三使留后兼行营招讨使，当日东还；王建送至新都跪拜告别。韦昭度到京师后被任东都留守。", "phases": [], "location_name": "成都行营、新都、京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ad1c0aa7-b49c-5b90-97d8-f21bf10e818f"}, {"title": "王建守剑门拒东军并急攻成都", "start_year": 891, "end_year": 891, "time_original": "891年四月庚子后；韦昭度出剑门后", "dynasty": "唐", "description": "韦昭度刚出剑门，王建即派兵守之，不再容东军进入；又急攻成都，环城烽堑亘五十里。", "phases": [], "location_name": "剑门、成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "482f4be8-ec97-5cd6-9011-427492495cd8"}, {"title": "王鹞诈亡入成都扰乱守方", "start_year": 891, "end_year": 891, "time_original": "891年四月后条；急围成都时", "dynasty": "唐", "description": "狗屠王鹞请诈作得罪王建而逃入成都。入见陈敬瑄田令孜时称王建军疲粮尽将退，出而卖茶时暗向吏民称王建英武、兵强，致守方懈备而众心惧。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0f677762-4c2a-5a79-963a-c5bfa260fa33"}, {"title": "郑渥诈降侦成都后改名王宗渥", "start_year": 891, "end_year": 891, "time_original": "891年四月后条；围成都时", "dynasty": "唐", "description": "王建遣京兆郑渥诈降侦察。陈敬瑄任其为将、令登城，郑渥又用计得归，王建因而知城中虚实，任其亲从都指挥使，改姓名为王宗渥。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "99964410-8d3d-54d0-96fc-c2002612508c"}, {"title": "周岳由武安改任岭南西道", "start_year": 891, "end_year": 891, "time_original": "891年四月后条；具体日未载", "dynasty": "唐", "description": "朝廷以武安节度使周岳为岭南西道节度使。", "phases": [], "location_name": "武安、岭南西道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d88a0808-73ff-56f1-ba3e-757985321958"}, {"title": "李克用败赫连铎于河上，围云州", "start_year": 891, "end_year": 891, "time_original": "891年四月后条；具体日未载", "dynasty": "唐", "description": "李克用大举进击赫连铎，在河上击败其军，进围云州。", "phases": [], "location_name": "河上、云州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6720b26f-e0f1-5a4e-87cd-531066bebf16"}, {"title": "刘威朱延寿黄池击孙儒大败", "start_year": 891, "end_year": 891, "time_original": "891年四月后条；五月大水前", "dynasty": "唐", "description": "杨行密遣刘威、朱延寿率兵三万在黄池攻击孙儒，刘威等大败。", "phases": [], "location_name": "黄池", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ba0ef369-ea89-531b-9bcc-010a7697ca66"}, {"title": "黄池洪水淹营，孙儒还扬州", "start_year": 891, "end_year": 891, "time_original": "891年五月", "dynasty": "唐", "description": "孙儒驻军黄池，五月洪水使诸营被淹，遂回扬州。", "phases": [], "location_name": "黄池、扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "efb2ef9a-7c15-5cba-b34b-2c273daa29c4"}, {"title": "孙儒遣康暀据和州、安景思据滁州", "start_year": 891, "end_year": 891, "time_original": "891年五月条；还扬州时", "dynasty": "唐", "description": "孙儒使康暀据和州，安景思据滁州。", "phases": [], "location_name": "和州、滁州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "66f2d387-ae43-50ca-a401-f2f457b2df3e"}, {"title": "皇子李祐封德王", "start_year": 891, "end_year": 891, "time_original": "891年五月丙午", "dynasty": "唐", "description": "朝廷立皇子祐为德王。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "27837bdb-ff76-5361-a35a-75106399b892"}, {"title": "李神福攻和滁，康暀降安景思走", "start_year": 891, "end_year": 891, "time_original": "891年五月后条；具体日未载", "dynasty": "唐", "description": "杨行密遣李神福攻和州、滁州，康暀投降，安景思逃走。", "phases": [], "location_name": "和州、滁州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "654bd1ee-b5f1-56fe-9ed4-0103cc08ecf1"}, {"title": "赫连铎云州食尽，奔吐谷浑后归幽州", "start_year": 891, "end_year": 891, "time_original": "891年秋七月及其后", "dynasty": "唐", "description": "李克用急攻云州，赫连铎粮尽，逃往吐谷浑部，随后归幽州。", "phases": [], "location_name": "云州、吐谷浑部、幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8aa2a988-baba-5cd3-b9a4-ea855648ffe8"}, {"title": "李克用表石善友为大同防御使", "start_year": 891, "end_year": 891, "time_original": "891年七月条；云州守方出走后", "dynasty": "唐", "description": "李克用上表请以大将石善友为大同防御使。", "phases": [], "location_name": "大同", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5f46aa96-6cc0-50d3-9491-759e488765b5"}]'::jsonb)
