INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "成都粮食短缺，弃儿满路，居民偷从行营贩米入城。韦昭度与陈敬瑄均准其救饥，贩米渐多但数量极少，米价高昂，饿死者众。", "citation": "卷258·大顺二年（891）·zztj-v258-y0891-p009·原文件第85行", "note": "原文：成都城中乏食，弃儿满路。民有潜入行营贩米入城者，逻者得之，以白韦昭度，昭度曰：“满城饥甚，忍不救之！”释勿问。亦有白陈敬瑄者，敬瑄曰：“吾恨无术以救饿者，彼能如是，勿禁也。”由是贩者浸多，然所致不过斗升，截筒，径寸半，深五分，量米而鬻之，每筒百馀钱，饿殍狼籍。军民强弱相陵，将吏斩之不能禁；乃更为酷法，或断腰，或斜劈，死者相继而为者不止。人耳目既熟，不以为惧。吏民日窘，多谋出降，敬瑄悉捕其族党杀之，惨毒备至。内外都指挥使、眉州刺史成都徐耕，性仁恕，所全活数千人。田令孜曰：“公掌生杀而不刑一人，有异志邪？”耕惧，夜，取俘囚戮于市。；核对说明：米筒尺寸、价格和饥民惨状按书载，不换算现代物价；为本次围城背景，不定首次饥荒日。", "status": "draft", "id": "92acdbcd-e090-5def-82dd-6e3d86f7c42f", "subject_id": "1b0888d7-ed15-5839-8328-280830cbb99d", "source_id": "d3357220-e689-5ebf-b1a9-6ec7b921c7de"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "891年四月后条；围城期间", "citation": "卷258·大顺二年（891）·zztj-v258-y0891-p009·原文件第85行", "note": "原文：成都城中乏食，弃儿满路。民有潜入行营贩米入城者，逻者得之，以白韦昭度，昭度曰：“满城饥甚，忍不救之！”释勿问。亦有白陈敬瑄者，敬瑄曰：“吾恨无术以救饿者，彼能如是，勿禁也。”由是贩者浸多，然所致不过斗升，截筒，径寸半，深五分，量米而鬻之，每筒百馀钱，饿殍狼籍。军民强弱相陵，将吏斩之不能禁；乃更为酷法，或断腰，或斜劈，死者相继而为者不止。人耳目既熟，不以为惧。吏民日窘，多谋出降，敬瑄悉捕其族党杀之，惨毒备至。内外都指挥使、眉州刺史成都徐耕，性仁恕，所全活数千人。田令孜曰：“公掌生杀而不刑一人，有异志邪？”耕惧，夜，取俘囚戮于市。；核对说明：米筒尺寸、价格和饥民惨状按书载，不换算现代物价；为本次围城背景，不定首次饥荒日。", "status": "draft", "id": "245a0805-b283-51f5-8f0d-77bcae47d833", "subject_id": "1b0888d7-ed15-5839-8328-280830cbb99d", "source_id": "d3357220-e689-5ebf-b1a9-6ec7b921c7de"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记韦昭度：允贩米救饥者。", "citation": "卷258·大顺二年（891）·zztj-v258-y0891-p009·原文件第85行", "note": "原文：成都城中乏食，弃儿满路。民有潜入行营贩米入城者，逻者得之，以白韦昭度，昭度曰：“满城饥甚，忍不救之！”释勿问。亦有白陈敬瑄者，敬瑄曰：“吾恨无术以救饿者，彼能如是，勿禁也。”由是贩者浸多，然所致不过斗升，截筒，径寸半，深五分，量米而鬻之，每筒百馀钱，饿殍狼籍。军民强弱相陵，将吏斩之不能禁；乃更为酷法，或断腰，或斜劈，死者相继而为者不止。人耳目既熟，不以为惧。吏民日窘，多谋出降，敬瑄悉捕其族党杀之，惨毒备至。内外都指挥使、眉州刺史成都徐耕，性仁恕，所全活数千人。田令孜曰：“公掌生杀而不刑一人，有异志邪？”耕惧，夜，取俘囚戮于市。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "0d1ed825-b2d7-51b4-ade